from fractions import Fraction as Q
from math import factorial,comb
from functools import lru_cache
def clean(P):return {e:c for e,c in P.items() if c}
def add(P,R):
    A=P.copy()
    for e,c in R.items():A[e]=A.get(e,Q(0))+c
    return clean(A)
def scale(c,P):return clean({e:c*v for e,v in P.items()})
def mul(P,R):
    A={}
    for e,c in P.items():
        for f,d in R.items():
            k=tuple(x+y for x,y in zip(e,f));A[k]=A.get(k,Q(0))+c*d
    return clean(A)
def moment(p,a,r):return Q(0) if r%p else Q(factorial(r),factorial(r//p))*a**(r//p)
def cond(P,k,p,a):
    A={}
    for e,c in P.items():
        for i in range(k,len(e)):c*=moment(p,a,e[i])
        f=tuple(v if i<k else 0 for i,v in enumerate(e));A[f]=A.get(f,Q(0))+c
    return clean(A)
def jet(P,j,q):
    return clean({tuple(v if i<j else 0 for i,v in enumerate(e)):c
                  for e,c in P.items() if e[j]==q})
@lru_cache(None)
def position_monomial(e):
    n=len(e);A={(0,)*n:Q(1)}
    for i,r in enumerate(e):
        B={}
        for k in ([r] if i==0 else range(r+1)):
            f=[0]*n;f[i]=k
            if i:f[i-1]=r-k
            B[tuple(f)]=Q(comb(r,k)*(-1)**(r-k))
        A=mul(A,B)
    return A
def norm(P):
    A={}
    for e,c in P.items():A=add(A,scale(c,position_monomial(e)))
    return sum(factorial(sum(e))*abs(c) for e,c in A.items())
